GROUPS = [
 dict(level='pre-a1',id='LEX-PRE-17',title='Dizer como está e pedir algo simples',after='FND-05',words=['happy','sad','hungry','thirsty','hot','cold'],
 situation='Cartões bilíngues: happy/feliz, sad/triste, hungry/com fome, thirsty/com sede, hot/com calor, cold/com frio. Trabalhe primeiro hungry/thirsty; depois happy/sad; por último hot/cold, em encontros diferentes se necessário. Rodada 1: Ana declara sede e pede água; Rui declara fome e pede pão. A recebe um cartão e fala I’m thirsty. Water, please ou I’m hungry. Bread, please; B aponta pedido e confirma Water? / Bread? Rodada 2: cartões Jo triste e Lee feliz; só declarar I’m sad/happy, sem explicar causa. Rodada 3: personagem com calor ou frio; destinatário marca sensação em português. Texto substitui expressão facial como pista.',
 result='Ana: I’m thirsty. Water, please. Rui: I’m hungry. Bread, please. Jo: I’m sad. Lee: I’m happy. Hot/cold descrevem sensação declarada, não febre nem temperatura medida. Confirmar pedido não obriga entrega real; usar cartões. Fala com apoio e seleção por gesto são evidências diferentes.',
 phon='O colega ouve uma declaração e escolhe rótulo em português, depois restitui palavra inglesa com modelo. Não inferir sensação por rosto; alternar cartões. Sem voz de parceiro, registrar leitura e ensaio, não escuta.',
 pitfall='Não exigir autodescrição emocional. Cold já existe em A1 em outro contexto; novo registro pré-A1 trabalha bloco pessoal, não palavra inédita absoluta. Dar números de tentativas e apoios reais, sem classificar personalidade.'),
 dict(level='a1',id='LEX-A1-12',title='Contar sentimentos e primeiras impressões',after='A1-05',words=['angry','worried','excited','bored','friendly','shy'],
 situation='Cartões: Ana está preocupada com teste amanhã; Rui animado com passeio sábado; Jo zangado com barulho agora; Lee entediado na espera. Kim diz “I feel shy with new people”; Nara cumprimenta cordialmente e oferece ajuda. Em duas rodadas, A representa dois personagens e B preenche Nome/Como se sente/Motivo informado. Apoio: about = com/em relação a; noise = barulho; test = teste; trip = passeio/viagem. Depois comparem impressão de Nara (“She seems friendly”) e declaração de Kim (“Kim says: I feel shy”). Não identificar sentimento só por silêncio.',
 result='I’m worried about the test. I’m excited about the trip. I’m angry about the noise. I’m bored. Kim se autodescreve shy; Nara parece friendly pelo comportamento descrito, sem provar amizade íntima. The wait is boring / I’m bored pode ser usado como contraste com tradução. Motivos não informados não devem ser inventados.',
 phon='Contraste angry e hungry, retomando pré-A1 com significado antes de ensaio oral. Ouça bored/boring em frase, marcando pessoa e atividade. Não exigir perfeição sonora para registrar informação recuperada.',
 pitfall='Some tarefas permitem opinião, outras pedem fonte. Ensinar seems e says como apoios, sem obrigar nova teoria gramatical. Excited neste uso é expectativa animada. Dividir seis entradas em três pares se necessário.'),
 dict(level='a2',id='LEX-A2-12',title='Relatar uma mudança de estado sem apagar nuances',after='A2-07',words=['nervous','surprised','lonely','upset','calm','proud'],
 situation='Texto autoral curto: “Yesterday Ana was nervous about her first presentation. Today the time is confirmed and she feels calm. She is surprised by a message from an old friend. She is proud of finishing the presentation, although she wants to improve it.” Segundo cartão: “Lee lives alone but does not feel lonely. Lee is upset about a cancelled visit and explains: I feel sad, not angry.” A recebe Ana, B recebe Lee; entrevistem-se com When? / About what? / Sad or angry? e montem síntese de 50–80 palavras. Troquem cartões após registrar primeira interpretação.',
 result='Ana nervous ontem, calm hoje, surprised pela mensagem, proud por concluir, não por perfeição comprovada. Lee alone não lonely; upset foi esclarecido como sad, não angry. Não inferir que surpresa foi positiva só porque amigo escreveu. Modelo: Ana was nervous yesterday, but feels calm now. Lee lives alone without feeling lonely, and is sad about the cancelled visit.',
 phon='Destaque YESTERDAY / NOW e ALONE / NOT LONELY. O parceiro devolve cronologia e contraste, permitindo repetição. A meta é preservar informação, não reproduzir uma emoção na voz.',
 pitfall='Termos de emoção não são diagnósticos. Apoio although = embora pode ser glossado ou substituído por but. Não transformar orgulho em arrogância nem calma presente em prova de ausência de qualquer preocupação.'),
 dict(level='b1',id='LEX-B1-12',title='Relatar reações diferentes a um mesmo acontecimento',after='B1-08',words=['relieved','embarrassed','confident','annoyed','grateful','homesick'],
 situation='Durante viagem fictícia de estudo, Ana perdeu a confirmação da sala e ficou constrangida ao pedir novamente. Recebeu confirmação e relata alívio; equipamento ainda não foi conferido. Confia na própria preparação e agradece a Jo por conferir as datas. Rui relata irritação com mudança de horário, mas desconhece motivo. Ana gosta da viagem e sente saudade de casa às vezes. A relata experiência de Ana; B recebe reação de Rui. Compare perspectivas e escreva mensagem de 90–120 palavras sem atribuir culpa ou encerrar pendências.',
 result='Ana felt embarrassed about requesting the details again and relieved when the room was confirmed. She is confident about her preparation, but equipment is pending. She is grateful to Jo for checking the dates. Rui was annoyed about the change; cause unknown. Ana enjoys the trip but feels homesick sometimes. Relieved não significa tudo resolvido, nem homesick sick at home.',
 phon='Destaque objeto da reação: relieved ABOUT THE ROOM / confident ABOUT PREPARATION. O interlocutor preenche sentimento/motivo/fonte. Praticar grateful TO Jo FOR checking com blocos de sentido.',
 pitfall='Não tornar comunicação afetiva sinônimo de uma interpretação positiva obrigatória. A mesma pessoa pode gostar da viagem e sentir saudade. Aceitar sentimento atribuído com fonte e discordância respeitosa na discussão.'),
 dict(level='b2',id='LEX-B2-14',title='Negociar apoio sem presumir capacidade ou intenção',after='B2-08',words=['frustrated','overwhelmed','self-conscious','sympathetic','considerate','insensitive'],
 situation='Nota fictícia: “Jo says she feels overwhelmed by six simultaneous requests, not by the difficulty of any one task. Repeated changes have left her frustrated. She also feels self-conscious about recording her voice. Her manager listens sympathetically but cannot move Friday’s external deadline.” Outra mensagem: Lee perguntou preferências e ofereceu repartir trabalho; Jo achou isso atencioso. Um comentário “You just need to try harder” foi percebido por Jo como insensível; autor não explicou intenção. A negocia prioridades, B sintetiza perspectivas em linguagem cuidadosa. Produza resposta de 120–160 palavras preservando limite de prazo e possibilidade de apoio.',
 result='Jo feels overwhelmed by simultaneous volume and frustrated by changes; não prova incapacidade geral. She feels self-conscious about recording, not necessarily unable to speak. The manager is sympathetic but deadline remains. Lee’s offer was considered considerate. Jo found the other comment insensitive; intenção não estabelecida. Proposta possível: distribute tasks and agree priorities, mantendo aprovação da distribuição como etapa futura.',
 phon='Use atribuição audível: JO FOUND it insensitive / the author’s intention is UNKNOWN. Parceiro distingue percepção, ação e intenção. Leitura neutra também pode comunicar com clareza.',
 pitfall='Sympathetic não é tradução automática de simpático, e self-conscious não é mero autoconhecimento. Não exigir relato de vulnerabilidade real. Uma mensagem empática não garante solução de restrições materiais.'),
 dict(level='c1',id='LEX-C1-08',title='Interpretar ambivalência e reformular relatos com delicadeza',after='B2-08',words=['apprehensive','disillusioned','conflicted','wistful','hold a grudge','put at ease'],
 situation='Microficção autoral: “Mara welcomed the new role but worried about leaving her neighbourhood. She remembered the open doors and evening conversations: Perhaps things were simpler then, she said. She had lost confidence in the selection process after a promise was broken, but still admired two colleagues. One colleague thought she resented Jo for a past disagreement. Mara replied: I disagree with Jo, but I don’t hold a grudge. A clear explanation of the first week helped her feel more comfortable, though it did not remove every concern.” A interpreta; B distingue declaração, inferência e leitura contestada. Escreva síntese de 140–180 palavras que preserve sentimentos simultâneos e reformule para destinatário não especialista.',
 result='Mara is apprehensive about the transition and conflicted about its gains and losses. She is disillusioned with the process, not necessarily all colleagues. The recollection may sound wistful; não prova desejo de retorno. A colleague’s grudge interpretation is disputed by Mara’s explicit statement. The explanation put her at ease to some extent, not completely. Paráfrase clara pode substituir vocabulário-alvo, registrando o que não foi observado produtivamente.',
 phon='Compare leitura da frase nostálgica em tons diferentes; indique quais sentidos vêm do texto e quais foram acrescentados pela execução. O ouvinte identifica ressalva “to some extent”, preservando limite do efeito.',
 pitfall='Evitar gabarito psicológico fechado para wistful/conflicted. Avaliar plausibilidade textual e atribuição. Put someone at ease exige objeto; não é instrução para manipular emoção. Idiomatismo hold a grudge deve ser interpretado em contexto, não inferido de silêncio isolado.')
]
